from author import *
def q(a,b,c,d):return [a,b,c,d]
def sec(k,t,v,c):return(k,t,v,c)
def quiz(k,question,options,explain,correct=0):return(k,question,options,correct,explain)
lesson('M08-L01',q('نفس جسم التخزين ممكن يخدم مدخل أو عرض أو مكتب، لكن التقسيم وطريقة الوصول مش نسخة واحدة. هنثبت الجسم كتجربة ونغيّر اللي الوظيفة محتاجاه.','يمكن تكييف جسم تخزين مشترك لمدخل أو عرض أو مكتب، مع اختلاف المحتويات والوصول والحماية. ستعد ثلاث بطاقات تبرر التغييرات الوظيفية.','جسم التخزين نفسه ممكن يخدم المدخل أو العرض أو المكتب، لكن الاستخدام يغيّر التقسيم والوصول. بنقارن ثلاث تطبيقات ونوضح سبب كل تغيير.','A shared cabinet shell can serve an entrance, display or office, but contents and access change the interior. Produce three application cards that justify each functional change.'),[
sec('arrival',q('ابدأ بسيناريو الدخول','تحليل الوصول إلى المدخل','ابدأ بطريقة الدخول','Start with the arrival sequence'),q('في المدخل، سجّل الشخص داخل بإيه وبيحط كل حاجة فين: مفاتيح، شنطة أو حذاء. افصل الأشياء المتسخة عن النظيفة وحدد صينية قابلة للتنظيف بدل حبس الاتساخ في ركن مقفول. ارسم باب المكان وباب الوحدة وهما مفتوحين؛ فتح التخزين ما يعطلش الدخول. لو فيه مقعد، راجع دعمه كعنصر جلوس مستقل؛ وجود سطح فوق خزانة مش تصريح بالجلوس عليه.','سجّل ما يحمله المستخدم وتسلسل وضعه، وافصل المتسخ عن النظيف بوسيلة تنظيف قابلة للوصول. اختبر فتح باب الغرفة وباب الوحدة معاً وموقع المستخدم أثناء تبديل الحذاء. لا تعتمد سطح الخزانة مقعداً لمجرد ملاءمة شكله؛ يتطلب استخدام الجلوس دعماً ومراجعة أداء محددين.','سجّل وش مع المستخدم عند دخوله ووين يحط المفاتيح والشنطة والحذاء. افصل المتسخ عن النظيف وخلي التنظيف ممكن بدون تفكيك صعب. ارسم باب المدخل وباب الوحدة مفتوحين مع مكان الوقوف. وإذا فيه جلوس، راجع دعمه؛ سطح الخزانة ما يصير مقعد معتمد لمجرد شكله.','List carried items and their arrival sequence: keys, bag and shoes. Separate dirty from clean contents and provide accessible cleaning rather than trapping dirt in a closed corner. Draw room and cabinet doors open together, including the user position. A cabinet top is not automatically a seat; seating requires its own support and performance review.'),q('الوصول والتنظيف قبل شكل الواجهة.','يوضح المخطط الدخول والفتح وموقع المستخدم.','راجع الباب والمستخدم والتخزين مع بعض.','Check entrance, opening and user positions together.')),
sec('display',q('حوّل التخزين لعرض مقصود','تخطيط الرؤية والحماية في العرض','خطط للرؤية وحماية المعروض','Plan display visibility and protection'),q('في العرض، اعمل قائمة بالمقتنيات وحجمها وطريقة حملها والتنظيف حواليها. حدد قطعة أساسية ومساحة فاضية تساعد قراءتها بدل ملء كل رف. الزجاج والإضاءة قرارات وظيفية: راجع انعكاس الضوء والوصول للمقتنى ومصدر الكهرباء والصيانة. ما تختارش سمك زجاج أو قدرة رف من شكل الصورة؛ وثّق الحمل ونوع التثبيت وخلي اعتماد النظام لبياناته ومراجعته.','ابدأ بأبعاد المقتنيات وطريقة حملها وتنظيفها وحدد العنصر المحوري والفراغ حوله. راجع رؤية المقتنى مع انعكاس الزجاج والإضاءة، وإمكان استبدال المصدر الضوئي والوصول إلى الخدمة. لا تستنتج سماكة زجاج أو قدرة رف من المنظور؛ سجل الأحمال والدعم ومراجعة النظام المطلوبة.','قِس المقتنيات وحدد طريقة حملها والتنظيف حولها. اختر عنصر واضح ومساحة فاضية حوله بدل تكديس الرفوف. راجع انعكاس الزجاج والإضاءة ووصول الصيانة والكهرباء. سماكة الزجاج وتحمل الرف ما تنحسم من صورة؛ وثّق الحمل والدعم وارجع لبيانات النظام واعتماده.','Inventory object dimensions, support needs and cleaning access. Establish a focal object with surrounding space rather than filling every shelf. Check reflections from glazing and lighting, as well as access to replace the light source. Do not derive glass thickness or shelf capacity from a perspective image; record loads, support and the required system review.'),q('المقتنى ونطاق الرؤية والوصول تحدد التقسيم.','الرؤية والحماية والصيانة قرارات مترابطة.','الفراغ حول المعروض جزء من قرار العرض.','Visibility, protection and service access shape the display.')),
sec('office',q('كيّف الوحدة للملفات والمشاركة','تكييف التخزين للمكتب','كيّفها للملفات والاستخدام المشترك','Adapt storage to office workflows'),q('قِس عينة الملف أو الصندوق الفعلي، وحدد المستخدمين وتكرار الرجوع له ودرجة الخصوصية. الملفات اليومية مكانها مرتبط بمسار العمل، والمشتركة محتاجة تعريف واضح، والحساسة محتاجة تحكم في الوصول. راجع سحب الدرج مع كرسي المستخدم ومسار المرور، وثبات الوحدة حسب النظام. بطاقة التطبيق تذكر ما اتغير في الداخل أو القفل أو الكسوة وسببه، وما فضل مشتركًا في الجسم.','تقاس عينة الملف الفعلي مع تحديد المستخدم وتكرار الوصول وخصوصية المحتوى. يرتبط التخزين اليومي بمسار العمل، ويحتاج المشترك إلى تعريف، والحساس إلى تحكم مناسب في الوصول. اختبر امتداد الأدراج مع الكرسي والمرور وثبات النظام. وثق التعديلات في التقسيم أو الإغلاق أو التشطيب، والأجزاء المشتركة التي لم تتغير.','قِس الملف الحقيقي وحدد مين يستخدمه وكم مرة وخصوصيته. اليومي قريب من مسار العمل، والمشترك له تعريف واضح، والحساس له وصول مضبوط. راجع الدرج مفتوح مع الكرسي والمرور وثبات الوحدة حسب نظامها. بالبطاقة اكتب وش تغير بالتقسيم والقفل والتشطيب وليش، وش بقي مشترك.','Measure the actual file or box sample and identify users, access frequency and confidentiality. Daily storage follows the workflow; shared items need clear identification; sensitive contents require controlled access. Check extended drawers against chairs and circulation, and review system stability. Record which dividers, closures or finishes change, why they change and which shell parts remain common.'),q('ثلاث وظائف؛ جسم مشترك وتغييرات مبررة.','تتغير التفاصيل وفق المحتويات وطريقة الوصول.','سجّل المشترك والتغيير وسببه.','Keep the common shell separate from justified functional changes.'))],
(q('تمرين مقارنة: جسم افتراضي واحد له ثلاث فتحات. تطبيق المدخل يستخدم صينية للأحذية ومكانًا للمفاتيح؛ العرض يستخدم حيزًا لمقتنى محدد مع وصول للتنظيف؛ المكتب يستخدم فواصل طبقًا لعينة ملفات. لا نضيف درجًا وقفلًا للجميع تلقائيًا. نراجع الفتحات بعد تعريف المحتوى، ونعدّل الجسم نفسه إذا لم يحقق الاستخدام بدل إجبار الوظيفة عليه.','في تمرين جسم بثلاث فتحات، يحتاج المدخل صينية تنظيف، والعرض حيزاً للمقتنى، والمكتب فواصل لعينة الملفات. لا تعمم الدرج أو القفل على التطبيقات الثلاثة. إذا تعارض الجسم المشترك مع متطلب أساسي، يعدل مع توثيق السبب بدلاً من الحفاظ على التطابق الشكلي.','بتمرين جسم فيه ثلاث فتحات: المدخل يحتاج صينية تنظيف، والعرض حيز للمقتنى، والمكتب فواصل بحسب الملفات. مو كل تطبيق يحتاج نفس الدرج والقفل. إذا الجسم المشترك ما يخدم مطلب أساسي، نعدله ونسجل السبب بدل إجبار الاستخدام عليه.','Exercise: one hypothetical three-bay shell becomes an entrance cabinet with a cleaning tray, a display with object-specific space, or an office cabinet with file dividers. Do not add the same drawer and lock to all three. If the common shell prevents a core function, revise the shell and document the reason instead of forcing identical geometry.'),q('القرار: نشارك الجسم لما يخدم الوظيفة، ونبرر كل اختلاف.','القرار: اشتراك مشروط بأداء الوظيفة، لا تطابق مفروض.','القرار: المشترك يخدم الاستخدام، والتغيير له سبب.','Decision: share the shell only while it supports the required function.')),
[quiz('adapt',q('أول خطوة لتكييف الوحدة للمكتب؟','ما الخطوة الأولى لتكييف التخزين المكتبي؟','وش أول خطوة لتخزين المكتب؟','What should precede adapting office storage?'),q(['قياس الملفات وتحديد الوصول','نسخ رفوف العرض','اختيار لون القفل'],['قياس المحتوى وتعريف الوصول','نسخ العرض','لون القفل'],['قياس الملفات وتحديد الوصول','نسخ العرض','لون القفل'],['Measure contents and define access','Copy display shelves','Choose lock colour']),q('المحتوى وطريقة الوصول يحددوا التقسيم والحماية.','ينطلق التقسيم من المحتوى والوصول.','المحتوى والوصول يحددون التقسيم.','Contents and access establish the subdivision and protection.'))],
(q('اعمل ثلاث بطاقات لنفس الجسم: مدخل وعرض ومكتب، مع رسم فتح وتغيير وظيفي مبرر لكل تطبيق.','أعد ثلاث بطاقات تطبيق لجسم مشترك مع مخطط فتح وتبرير التغييرات.','جهز ثلاث بطاقات للجسم نفسه: مدخل وعرض ومكتب مع الفتح وسبب التغيير.','Prepare entrance, display and office cards for one shell, including opening plans and justified changes.'),q(['المحتوى والمستخدم','رسم الفتح والوصول','المشترك والتغييرات'],['المحتويات والوصول','مخططات الفتح','المشترك والتعديل'],['المحتوى والاستخدام','رسم الفتح','المشترك والتغيير'],['Contents and user','Opening/access plan','Common and changed parts']),q(['اختلافات مرتبطة بوظيفة','عدم تعارض الأبواب','فحص الدعم عند الحاجة'],['تعليل التغييرات','اختبار الفتح','تحديد مراجعة الدعم'],['سبب واضح للتغيير','فتح بلا تعارض','مراجعة الدعم'],['Function-based changes','Opening conflicts checked','Required support review identified'])),
(q('لازم الجسم يفضل واحد مهما كان الاستخدام؟','هل يجب الحفاظ على الجسم ذاته في كل تطبيق؟','لازم نفس الجسم بكل الحالات؟','Must the shell remain identical in every application?'),q('لا؛ المقارنة تكشف المشترك الممكن، ولو فيه تعارض وظيفي نعدّل الجسم ونشرح السبب.','لا؛ يعدل عند تعارضه مع وظيفة أساسية مع توثيق السبب.','لا، إذا عطّل وظيفة أساسية نعدله ونوضح السبب.','No. Revise it if it prevents a core function and record why.'),'office'))
lesson('M08-L02',q('المعيارية مش تكرار صناديق وخلاص. هنحدد واجهة اتصال مشتركة، ونعمل تكوينين بنفس الأجزاء، ثم نراجع الثبات والفتح في كل تكوين.','تحتاج المعيارية إلى أجزاء وواجهات اتصال متوافقة، لا تكرار الأشكال وحده. ستختبر تكوينين وسجل أجزاء ومراجعة مستقلة لكل وضع.','المعيارية مو صناديق متشابهة وبس. بنحدد اتصال مشترك ونركب تكوينين من نفس الأجزاء ونراجع كل وضع.','Modularity requires compatible interfaces, not merely repeated shapes. Build two arrangements from a shared part set and review access and stability in each.'),[
sec('grid',q('حدد شبكة وأبعاد خارجية واضحة','تعريف الشبكة والوحدة الخارجية','حدد الشبكة وحدود الوحدة','Define the grid and module envelope'),q('فرّق بين عرض الوحدة الخارجي والفتحة الداخلية. في تمرين نفترض أربع وحدات، عرض كل واحدة الخارجي 400 مم، بدون فواصل بينية. صف من أربع وحدات عرضه 1600 مم؛ تكوين من وحدتين جنب بعض عرضه 800 مم. الارتفاع في التكوين الرأسي يحتاج ارتفاع الوحدة ونظام التكديس. شبكة الأبعاد تنسق التكرار؛ ما تثبتش إن الوحدات صالحة للتكديس.','ميّز العرض الخارجي من الفتحة الصافية. نفترض تدريبياً أربع وحدات بعرض خارجي 400 مم ودون فواصل بينية؛ يبلغ عرض الصف 1600 مم، وعرض وحدتين 800 مم. لا يحسب ارتفاع التكديس من العرض، بل من ارتفاع الوحدة وتفصيل الربط. تشرح الشبكة التوافق الهندسي ولا تثبت صلاحية التكديس.','ميّز عرض الوحدة من بره عن الفتحة الداخلية. بتمرين أربع وحدات عرض كل وحدة 400 مم وبدون فواصل: الصف 1600 مم، ووحدتين جنب بعض 800 مم. ارتفاع التكوين يحتاج ارتفاع الوحدة وتفصيل التكديس. الشبكة تضبط المقاسات، لكنها ما تعتمد التكديس أو الثبات.','Distinguish external module width from clear internal opening. Assume four teaching modules, each 400 mm externally, with no intermediate gaps: a four-unit row is 1600 mm wide and a two-unit row is 800 mm. Stacked height depends on module height and the stacking detail, not width. A grid coordinates dimensions; it does not certify stackability.'),q('فرض التدريب: عرض خارجي 400 مم للوحدة.','الحساب للأبعاد الخارجية دون فواصل مفترضة.','الشبكة هندسة؛ التكديس يحتاج تحقق.','Exercise uses 400 mm external widths and no intermediate gaps.')),
sec('interfaces',q('ثبّت واجهات الربط والوصول','توحيد الواجهات مع حفظ إمكانية الخدمة','وحّد الربط وخلي الوصول متاح','Standardise interfaces and keep access'),q('سمّي الجسم المشترك A والرف B وغطاء النهاية C. اكتب موضع الربط ومرجعه واتجاهه والأجزاء اللي ينفع تعكسها فعلًا. نفس المقاس الخارجي مش معناه توافق تلقائي؛ اختلاف موضع الوصلة أو اتجاه الباب يمنع التبادل. اشرح الوصول للأداة وتسلسل الفك، وسجّل غطاء النهاية كجزء مختلف لو وجهه ظاهر. المعيارية تقل لما نحتاج تخريم جديد لكل ترتيب.','عرّف الجسم A والرف B وغطاء النهاية C، ووثق مرجع الوصلة واتجاهها وقابلية عكس الأجزاء. لا يكفي تساوي المقاس الخارجي لإثبات التبادل إذا اختلف موضع الربط أو فتح الباب. حدد وصول الأداة وتسلسل الفك، وميّز الغطاء الظاهر عند اختلاف تشطيبه. التعديل الموقعي المتكرر يحد من إعادة التكوين.','سمّ الجسم A والرف B وغطاء الطرف C. حدد مرجع الربط واتجاهه وهل الجزء ينعكس فعلًا. نفس المقاس ما يضمن التبادل إذا الوصلة أو فتح الباب مختلف. وضح وصول الأداة وترتيب الفك، وميّز غطاء الطرف إذا تشطيبه غير. كل تخريم جديد مطلوب يقلل سهولة إعادة التكوين.','Label the common shell A, shelf B and end cover C. Record connector datum, orientation and whether each part is genuinely reversible. Matching outside dimensions do not ensure interchangeability when connector positions or door handing differ. Show tool access and disassembly order, and distinguish a visible end cover when its finish differs. Repeated site drilling undermines reconfiguration.'),q('تعريف الجزء ومرجع الربط يسبق تبديله.','التبادل يحتاج تطابق الواجهة والاتجاه والوصول.','نفس المقاس وحده ما يكفي.','Interchangeability requires matching interfaces and orientation.')),
sec('reconfigure',q('راجع كل تكوين كحالة مستقلة','فحص التكوين وسجل الأجزاء','راجع كل ترتيب لحاله','Review each arrangement independently'),q('ارسم الأربع وحدات في صف، ثم تكوينًا من صفين ووحدتين بكل صف كاقتراح للمراجعة. طابق عدد A وB وC وحدد أي قطع ربط إضافية بدل إخفائها في الرسمة. افحص فتح الأبواب والسحب والوصول للخدمة ومسار الحمل لكل ترتيب. التكوين الأعلى يغيّر الثبات والدعم؛ ما تسمحش للمستخدم يكدّس وحدة غير مصممة للتكديس لمجرد إن الشبكة راكبة.','قارن صفاً أفقياً من أربع وحدات باقتراح من صفين، مع مطابقة عدد الأجسام والرفوف والأغطية وحصر الروابط الإضافية. افحص الفتح والخدمة ومسار القوى في كل تكوين. يؤدي تغيير الارتفاع إلى تغيير شروط الثبات والدعم؛ لا يعتمد التكديس إلا لنظام مصمم ومراجع لذلك، ولو تطابقت الشبكة.','ارسم أربع وحدات بصف، وبعدها اقتراح صفين بكل صف وحدتين. طابق قائمة الأجزاء وأظهر أي ربط إضافي. راجع الفتح والخدمة ومسار الحمل بكل ترتيب. زيادة الارتفاع تغير الثبات والدعم؛ توافق الشبكة ما يسمح بتكديس وحدات ما صممت لهذا الاستخدام.','Compare a four-module row with a proposed two-by-two arrangement. Reconcile shells, shelves and end covers and list additional connectors explicitly. Review openings, service access and load paths for each layout. Increased height changes stability and support conditions. A matching grid does not permit stacking a product that was not designed and reviewed for that use.'),q('تكوينان وقائمة واحدة؛ مراجعة مستقلة لكل تكوين.','إعادة الترتيب لا تنقل اعتماد الثبات تلقائياً.','عدّ الأجزاء وراجع الثبات والفتح من جديد.','Reconfiguration requires a fresh opening and support review.'))],
(q('في الفرض، أربع وحدات عرضها 400 مم تعمل صفًا بعرض 1600 مم. العميل طلب عرضًا 800 مم، فاقتُرح صفان. عدد الأجسام يظل أربعة، لكن روابط التكديس والدعم غير معتمدة. نقبل حساب العرض كتمرين، ونوقف اعتماد التكوين الرأسي لحد مراجعة النظام؛ ما نبيعهش كتغيير آمن جاهز.','للأربع وحدات ذات العرض 400 مم صف بعرض 1600 مم. يحقق اقتراح الصفين عرضاً 800 مم مع بقاء أربعة أجسام، لكنه يضيف مسألة ربط وثبات. يثبت الحساب الهندسي فقط، ويظل اعتماد التكوين الرأسي معلقاً على مراجعة نظام التكديس.','أربع وحدات بعرض 400 مم تعطي صف 1600 مم. طلب عرض 800 مم أدى لاقتراح صفين، وعدد الأجسام بقي أربعة. الحساب صحيح بحسب الفرض، لكن ربط التكديس والثبات يحتاج مراجعة؛ ما نعتبر الترتيب جاهز للاستخدام قبلها.','Four 400 mm modules make a 1600 mm row. A requested 800 mm width suggests two rows, retaining four shells. The width arithmetic works under the assumption, but stacking connections and stability are unverified. Accept the dimensional exercise while holding approval of the vertical arrangement until the system is reviewed.'),q('القرار: أربعة أجسام مشتركة، والتكديس معلق للتحقق.','القرار: إثبات العرض مع تعليق اعتماد التكديس.','القرار: الحساب مقبول والتكديس يحتاج اعتماد.','Decision: confirm width arithmetic; hold stacking approval.')),
[quiz('grid-width',q('أربع وحدات خارجية 400 مم بدون فواصل؛ عرض الصف؟','ما عرض أربع وحدات 400 مم دون فواصل؟','أربع وحدات 400 مم بدون فواصل، كم العرض؟','Four 400 mm external modules with no gaps: row width?'),q(['1600 مم','800 مم','400 مم'],['1600 مم','800 مم','400 مم'],['1600 مم','800 مم','400 مم'],['1600 mm','800 mm','400 mm']),q('4 × 400 = 1600 مم للأبعاد الخارجية في الفرض.','الحساب 4 × 400 = 1600 مم.','4 × 400 = 1600 مم حسب الفرض.','4 × 400 = 1600 mm under the stated assumption.'))],
(q('ارسم تكوينين للأربع وحدات وجهز سجل أجزاء وواجهات ربط ومراجعة ثبات لكل تكوين.','قدم تكوينين وسجل الأجزاء وواجهات الاتصال ومتطلبات اعتماد الثبات.','جهز ترتيبين وقائمة الأجزاء والربط ومراجعة الثبات لكل واحد.','Submit two arrangements, a shared parts register, interfaces and separate stability review requirements.'),q(['التكوينان والأبعاد','عدد الأجزاء والروابط','الفتح والثبات'],['تكوينان','سجل أجزاء وواجهات','فتح وثبات'],['ترتيبان','قائمة الأجزاء','فتح ودعم'],['Two dimensioned layouts','Part and connector quantities','Opening and stability review']),q(['حساب 1600 و800 صحيح','عدم إخفاء روابط جديدة','لا اعتماد تكديس ضمني'],['صحة حساب العرض','حصر الروابط','تعليق غير المتحقق'],['حساب العرض صحيح','الروابط واضحة','التكديس مشروط'],['Correct 1600/800 widths','Additional connectors explicit','No implied stacking approval'])),
(q('الوحدات المتساوية تنفع تتكدس؟','هل تساوي الوحدات يثبت صلاحية التكديس؟','كل وحدتين متساويتين ينفع يتكدسون؟','Do equal modules automatically stack safely?'),q('لا؛ لازم نظام مصمم للتكديس ومراجعة الربط والثبات والحمل.','لا؛ يلزم نظام مناسب ومراجعة القوى والربط والثبات.','لا، يحتاج نظام تكديس ومراجعة الربط والثبات والحمل.','No. Stacking requires a suitable system and review of connections, loads and stability.'),'reconfigure'))
lesson('M08-L03',q('الأثاث متعدد الوظائف لازم ينجح وهو مقفول ومفتوح وأثناء التحول. هنختبر مكتبًا قابلًا للطي داخل تخزين، ونفصل توفير المساحة عن سلامة الحركة.','تقاس فاعلية الأثاث متعدد الوظائف في حالات الإغلاق والاستخدام والتحول. ستراجع مكتباً قابلاً للطي مع التخزين والوصول والدعم والصيانة.','الأثاث متعدد الوظائف لازم يخدم كل وضع ومرحلة التحول بينهم. بنراجع مكتب قابل للطي داخل تخزين مع الحركة والدعم والصيانة.','Multifunction furniture must work when stored, deployed and moving between states. Review a fold-down desk within storage, including access, support and maintenance.'),[
sec('states',q('ارسم الحالات ومساحة التحول','تمثيل الحالات ومجال الحركة','ارسم كل وضع ومسار التحول','Map operating states and swept space'),q('ارسم المسقط في ثلاث لقطات: سطح مقفول، أثناء النزول، وسطح مفتوح مع كرسي ومستخدم. المساحة المشغولة أثناء التحول ممكن تزيد عن المساحة النهائية. علّم الحركة المتعارضة مع باب الغرفة أو درج التخزين، وراجع هل لازم تنقل حاجة كل مرة. لو التخزين مستخدم مع المكتب، لازم الفتحتين يتراجعوا مع بعض مش كل واحدة لوحدها.','مثل الإغلاق والتحول والاستخدام مع الكرسي والمستخدم. قد يتجاوز مجال الحركة الحيز المشغول في الحالة النهائية. اختبر تعارضه مع باب الغرفة والأدراج وحدد ما يجب نقله قبل التشغيل. إذا كان التخزين والمكتب مطلوبين في الوقت نفسه، تراجع الحركتان معاً ولا يكتفى بمخططين منفصلين.','ارسم المقفول وأثناء النزول والمفتوح مع المستخدم والكرسي. مجال الحركة ممكن يكون أكبر من الوضع النهائي. راجع الباب والدرج وحدد وش لازم ينشال قبل التشغيل. إذا المستخدم يحتاج المكتب والتخزين بنفس الوقت، افحص الحركتين مع بعض.','Draw stored, transitioning and working states with the chair and user. The swept movement envelope can exceed the final footprint. Check interference with room doors and storage drawers, and identify anything that must be moved before deployment. If desk and storage are needed simultaneously, review their movements together rather than in separate conflict-free drawings.'),q('مقفول، انتقال، استخدام: ثلاث حالات للمراجعة.','مجال الحركة يراجع بين الحالات لا عند نهايتها فقط.','التحول له حيز يحتاج فحص.','Review the transition envelope as well as the end positions.')),
sec('supportlock',q('افصل الدعم عن الحركة والقفل','تمييز الدعم والتوجيه والإقفال','ميّز الدعم والحركة والقفل','Separate support, movement and locking'),q('المفصلة تسمح بالدوران لكنها مش دليل كفاية على دعم سطح العمل. ارسم الحمل رايح للدعامات ثم الجسم والسطح الحامل، وحدد وسيلة تثبيت وضع الاستخدام ومنع الطي غير المقصود. علّم مناطق انحشار الأصابع وخطوة تشغيل القفل من موضع آمن. اختار مجموعة حركة ودعم متوافقة حسب بيانات المنتج؛ ما تركّبش آلية من رسم تعليمي أو تختبرها بحمل عشوائي.','تشرح المفصلة الدوران ولا تثبت وحدها كفاية الدعم. تتبع الحمل عبر الدعامات والجسم والسطح الحامل، وحدد تثبيت وضع التشغيل ومنع الانطواء غير المقصود. علّم مناطق الانحشار وكيفية تشغيل القفل. يتطلب التنفيذ مجموعة حركة ودعم متوافقة ومراجعة بياناتها، لا وصفة تثبيت أو حمل اختبار مرتجل.','المفصلة تحرك السطح، لكنها ما تثبت دعم سطح العمل لحالها. ارسم الحمل للدعامة ثم الجسم والسطح الحامل، ووضح قفل وضع الاستخدام ومنع الطي بالغلط. حدد مناطق انحشار الأصابع وطريقة تشغيل القفل. اعتمد مجموعة متوافقة من بيانات المنتج، مو آلية مأخوذة من رسم تعليمي.','A hinge explains rotation but does not by itself establish adequate worktop support. Trace load through supports, carcass and substrate; identify how the working position is secured against unintended folding. Mark pinch zones and safe lock operation. Select a compatible movement/support assembly from product data and review it; do not turn a teaching sketch into a fixing recipe or improvised load test.'),q('حركة ودعم وقفل: أدوار مختلفة داخل نظام واحد.','يرتبط اعتماد الآلية بالدعم والتثبيت ومناطق الانحشار.','المفصلة ما تعني اعتماد التحمل.','Movement, support and locking have distinct roles.')),
sec('service',q('خطط للصيانة وسلوك الاستخدام','تخطيط الصيانة وتسلسل الاستخدام','خطط للصيانة وطريقة التشغيل','Plan maintenance and operating sequence'),q('اكتب تسلسل الاستخدام: إخلاء المسار، فتح السطح، تأكيد وضع الدعم حسب تعليمات النظام، وبعدها وضع الأدوات. قبل الغلق تتشال الأدوات والكرسي من مجال الحركة. وفّر وصولًا لنقاط الضبط وقطع الاستبدال من غير تكسير التشطيب. لو فيه كهرباء، خلي مسارها بعيد عن الانحشار وحافظ على وصول الخدمة؛ تفاصيلها تعتمد على نظام مؤهل. سجّل فحصًا لكل وظيفة وبعد التحول.','وثق تسلسل إخلاء المسار والفتح والتحقق من وضع الدعم وفق النظام، ثم وضع الأدوات. يسبق الإغلاق إبعاد الأدوات والكرسي عن الحركة. حافظ على الوصول للضبط والاستبدال دون إتلاف التشطيب. عند وجود كهرباء، تراجع حمايتها من الانحشار وخدمتها ضمن تصميم مختص، مع فحص كل وظيفة وبعد الانتقال.','اكتب الخطوات: فضّي المسار، افتح السطح، تأكد من الدعم حسب تعليمات النظام، ثم حط الأدوات. قبل الغلق شيل الأدوات والكرسي من الحركة. خلي الضبط والاستبدال متاحين بدون تكسير التشطيب. إذا فيه كهرباء، راجع حمايتها من الانحشار ووصول خدمتها ضمن نظام مختص، وافحص كل وظيفة بعد التحول.','Document a sequence: clear the path, deploy the top, confirm support engagement according to the system, then place equipment. Remove equipment and chair from the movement envelope before closing. Retain access for adjustment and replacement without damaging finishes. If power is included, protect it from pinching and preserve service access through a qualified design. Check each function after transitions.'),q('تسلسل واضح ووصول للصيانة قبل اعتماد التنفيذ.','سهولة التحول تشمل الإخلاء والصيانة وإعادة الفحص.','الوظائف تتراجع بعد التحول كمان.','Operating sequence and service access belong in the design.'))],
(q('في غرفة صغيرة، سطح مكتب ينزل قدام درج ملفات. الرسمة وهو مقفول تبدو موفرة، لكن في وضع العمل السطح يمنع فتح الدرج المطلوب يوميًا. ننقل الدرج إلى جانب متاح أو نغير الوظيفة المتزامنة، ثم نراجع الحركة والدعم من جديد. اختصار الأبعاد وحده لم يحل الاحتياج.','يمنع سطح مكتب مفتوح الوصول إلى درج ملفات يومي رغم نجاح مخطط الإغلاق. ينقل الدرج إلى جانب متاح أو يعدل البرنامج الوظيفي، ثم تعاد مراجعة مجال الحركة والدعم. يقاس النجاح بإمكان أداء الاستخدام المطلوب، لا بصغر الحيز المغلق وحده.','سطح المكتب وهو مفتوح يمنع درج الملفات اليومي رغم أن وضع الغلق مرتب. ننقل الدرج لجانب متاح أو نعدل الوظيفة المطلوبة، وبعدها نراجع الحركة والدعم. توفير المساحة وهو مقفول لحاله ما يثبت نجاح التصميم.','A fold-down desktop blocks the daily file drawer when deployed, although the closed arrangement looks compact. Relocate the drawer to an accessible side or revise the simultaneous-use requirement, then review movement and support again. A small stored footprint alone has not solved the user need.'),q('القرار: نحل تعارض الاستخدام المتزامن ثم نراجع النظام.','القرار: تصحيح الوصول قبل اعتماد تعدد الوظائف.','القرار: الوصول أثناء العمل لازم يتحقق.','Decision: resolve simultaneous-use access before approving the concept.')),
[quiz('transition',q('أي مراجعة تكشف تعارض التحول؟','ما الفحص الذي يكشف تعارض التحول؟','وش يوضح تعارض التحول؟','Which review reveals transition conflicts?'),q(['مجال الحركة مع المستخدم والجوار','شكل الوحدة مقفولة فقط','لون المفصلة'],['مجال الحركة والمستخدم والجوار','الإغلاق فقط','لون المفصلة'],['مجال الحركة مع المستخدم والجوار','المقفول فقط','لون المفصلة'],['Swept movement with user and neighbours','Stored appearance only','Hinge colour']),q('التعارض ممكن يظهر بين الوضعين أو أثناء الاستخدام المتزامن.','قد ينشأ التعارض أثناء الانتقال أو الاستخدام المتزامن.','التعارض قد يكون بين الوضعين أو مع الاستخدام المتزامن.','A conflict may occur between end positions or during simultaneous use.'))],
(q('ارسم مكتبًا مطويًا ومفتوحًا ومرحلة التحول، وحدد الدعم والقفل ومناطق الانحشار ووصول الصيانة.','قدم الحالات الثلاث ومسار القوى والإقفال والانحشار وخطة صيانة وتحقيق.','جهز الحالات الثلاث والدعم والقفل ومناطق الانحشار ووصول الخدمة.','Submit three operating states, load path, locking, pinch zones and a maintenance/verification plan.'),q(['الحالات ومجال الحركة','الدعم والقفل','التشغيل والصيانة'],['حالات وحركة','دعم وإقفال','خدمة وتحقق'],['الأوضاع والحركة','الدعم والقفل','تشغيل وخدمة'],['States and swept envelope','Support and locking','Operation and service']),q(['اختبار الاستخدام المتزامن','عدم اعتبار المفصلة دعمًا كافيًا','وصول للاستبدال'],['حل التعارض','فصل أدوار الآلية','إمكان الصيانة'],['حل تعارض الاستخدام','دعم موثق','صيانة متاحة'],['Simultaneous use checked','Hinge not assumed sufficient support','Replacement access retained'])),
(q('أي مفصلة تنفع لمكتب قابل للطي؟','هل تكفي أي مفصلة لمكتب مطوي؟','أي مفصلة تكفي للمكتب؟','Will any hinge suit a folding desk?'),q('لا؛ الحركة والدعم والقفل والتثبيت لازم يتراجعوا كنظام متوافق مع الاستخدام.','لا؛ تراجع الحركة والدعم والإقفال والتثبيت كنظام كامل.','لا، لازم حركة ودعم وقفل وتثبيت متوافقين مع الاستخدام.','No. Movement, support, locking and fixing must be reviewed as a compatible system.'),'supportlock'))
lesson('M09-L01',q('توزيع المعيشة يبدأ بمين بيقعد وبيعمل إيه، مش بصورة كنبة. هنقارن جلوسًا للحوار وجلوسًا للمشاهدة ونختبر الحركة في الحالتين.','ينطلق توزيع المعيشة من أنشطة المستخدمين وعلاقات الجلوس والحركة. ستقارن بديلين للحوار والمشاهدة مع نقاط قبول قابلة للمراجعة.','توزيع المعيشة يبدأ بالمستخدم والنشاط. بنقارن بديل للحوار وبديل للمشاهدة ونفحص الحركة والوصول بكل واحد.','Living-space planning starts with people and activities. Compare conversation and viewing arrangements, testing circulation and access against explicit acceptance points.'),[
sec('activities',q('حدد الأنشطة ونقطة التركيز','تعريف الأنشطة وعلاقات الجلوس','حدد النشاط واتجاه الجلوس','Define activities and seating relationships'),q('اكتب عدد المستخدمين في اليوم العادي وعند الضيافة، وهل الأولوية للكلام أو المشاهدة أو القراءة. الحوار يحتاج علاقة تسمح بتبادل النظر؛ المشاهدة تحتاج اتجاهًا واضحًا للشاشة من المقاعد المقصودة. ما تخلطش عدد أماكن الجلوس مع الراحة الفعلية أو حجم الشاشة. ارسم أسهم النظر والأنشطة، وعلّم المقاعد اللي بتحتاج التفافًا غير مريح للمهمة المطلوبة.','حدد المستخدمين في الوضع اليومي والضيافة وأولوية الحوار أو المشاهدة أو القراءة. تتطلب المحادثة علاقة بصرية متبادلة، بينما تتطلب المشاهدة اتجاهاً مناسباً نحو الشاشة. لا يثبت عدد المقاعد جودة استخدامها. ارسم خطوط النظر وحدد المقاعد التي تتطلب التفافاً غير ملائم للنشاط المطلوب.','سجّل عدد المستخدمين يوميًا ومع الضيوف وأولوية الكلام أو المشاهدة أو القراءة. الحوار يحتاج تواصل بالنظر، والمشاهدة تحتاج اتجاه مناسب للشاشة. عدد المقاعد ما يثبت الراحة. ارسم اتجاه النظر وعلّم أي مقعد يحتاج التفاف مزعج للمهمة المطلوبة.','Record everyday and guest occupancy and priorities for conversation, viewing or reading. Conversation needs reciprocal sightlines; viewing needs a suitable orientation to the screen from the intended seats. Seat count alone does not establish usability. Draw sightlines and identify seats requiring an awkward turn for the requested activity; do not derive seating comfort from screen size.'),q('نشاط واضح ثم علاقة جلوس مناسبة.','تراجع خطوط النظر وفق المهمة المقصودة.','العدد وحده ما يكفي لتقييم الجلسة.','Judge sightlines against the intended activity.')),
sec('circulation',q('ارسم الحركة مع الأثاث مستخدم','اختبار المرور أثناء الاستخدام','راجع المرور والأثاث مستخدم','Test circulation during use'),q('حدد الطريق من المدخل للغرف أو الشرفة قبل توزيع القطع. أضف فتح الأبواب وسحب الكرسي واستعمال الطاولة، مش مستطيلات الأثاث المقفول بس. افصل المسار العابر قدر الإمكان عن قلب الحوار. قِس أضيق نقطة في كل حالة وقارنها بمتطلبات المستخدم والمشروع الموثقة؛ رقم فراغ واحد من صورة مش قاعدة لكل البيوت ولا دليل إتاحة معتمد.','ارسم المسار من المدخل إلى الوجهات مع فتح الأبواب وتحريك الكراسي واستخدام الطاولة. تجنب مرور الحركة العابرة في قلب المحادثة عندما يسمح البرنامج بذلك. سجل أضيق نقطة في الحالات الفعلية وقارنها بمتطلبات المشروع والمستخدم الموثقة. لا يعمم رقم من صورة على جميع البيئات أو متطلبات الإتاحة.','ارسم طريق المدخل للوجهات مع فتح الأبواب وتحريك الكرسي واستخدام الطاولة. حاول ما يقطع المرور قلب الجلسة. قِس أضيق نقطة بكل وضع وقارنها بمتطلبات المستخدم والمشروع. فراغ من صورة ما يصير قاعدة عامة ولا إثبات إتاحة.','Map routes from the entrance to destinations, including open doors, moved chairs and table use. Where the brief allows, keep through-traffic outside the conversation group. Measure the narrowest point in realistic operating states and compare it with documented user and project requirements. A clearance copied from an image is not a universal rule or evidence of accessibility compliance.'),q('راجع أضيق نقطة في وضع الاستخدام.','الممر يختبر مع حركة الأبواب والمستخدمين.','الأثاث المستخدم غير مخطط المقفول.','Measure bottlenecks in occupied and opening states.')),
sec('alternatives',q('قارن البدائل بنفس شروط القبول','مقارنة البدائل وفق معايير ثابتة','قارن البدائل بشروط واحدة','Compare layouts using the same acceptance points'),q('جهّز A للحوار وB للمشاهدة بنفس حدود الغرفة ونفس عدد المستخدمين المفترض. سجّل لكل بديل: وضوح النظر، المسار العابر، فتح الأبواب والوصول للطاولة. لو فيه تعارض، اشرح التنازل بدل ما تغيّر المقياس لتجميل البديل. جرّب مواقع الجلوس بعلامات أرضية ونموذج بسيط قبل اعتماد القطع؛ الصورة المتناظرة ممكن تبقى أقل ملاءمة للوظيفة.','ثبت حدود الغرفة وعدد المستخدمين ثم قارن A للحوار وB للمشاهدة. سجل النظر والمرور وفتح الأبواب والوصول للطاولة وفق المعايير نفسها. اشرح التنازلات ولا تغير مقياس الرسم لتحسين العرض. يمكن مراجعة المواقع بعلامات أرضية ونموذج استخدام قبل اعتماد القطع؛ التناظر وحده ليس معيار النجاح.','خلّ حدود الغرفة وعدد المستخدمين ثابتين وقارن A للحوار وB للمشاهدة. سجل النظر والمرور والفتح والوصول للطاولة بنفس الشروط. وضّح التنازل إذا ظهر تعارض ولا تغير مقياس الرسم. جرّب المواضع بعلامات أرضية قبل الاعتماد؛ التناظر لحاله ما يثبت نجاح الوظيفة.','Keep room boundaries and assumed occupancy fixed when comparing A for conversation with B for viewing. Assess sightlines, through-routes, door opening and table access using the same criteria. Record trade-offs rather than changing drawing scale to flatter a proposal. Floor markings and a simple use mock-up can test positions before selection; symmetry alone is not a functional pass.'),q('معايير ثابتة تكشف التنازل بين البديلين.','الاختيار مرتبط بالأولوية ودليل الاستخدام.','اختبر الوظيفة قبل اعتماد التكوين.','Use common criteria and state the trade-off.'))],
(q('أسرة حددت الحوار أولوية والشرفة مستخدمة يوميًا. A يقابل المقاعد لكنه يحط كرسيًا في طريق الشرفة، وB ينقل الكرسي لجانب المجموعة ويحافظ على النظر. نختار B بشرط تأكيد أضيق ممر وفتح باب الشرفة موقعيًا؛ ما نضيفش مقعدًا خامسًا لو هيعيد التعارض.','تحدد الأسرة الحوار أولوية والوصول اليومي إلى الشرفة شرطاً. يحقق A تقابل المقاعد لكنه يعرقل المسار، بينما ينقل B الكرسي إلى جانب المجموعة مع بقاء التواصل البصري. يرجح B مع تحقق الموقع من أضيق مرور وفتح الباب قبل الاعتماد.','الأسرة تبغى حوار ووصول يومي للشرفة. A يقابل المقاعد لكن كرسيه يعطل الطريق، وB ينقل الكرسي لجانب الجلسة ويحافظ على النظر. نرجح B بشرط التحقق بالموقع من أضيق ممر وفتح الباب، وما نضيف مقعد يرجع التعارض.','The family prioritises conversation and daily balcony access. A faces seats toward each other but places a chair in the balcony route. B moves the chair to the side while retaining visual connection. Prefer B subject to checking the narrowest route and balcony door operation on site; an extra seat must not reintroduce the conflict.'),q('القرار: B يحقق الأولوية مع تحقق المرور والفتح.','القرار: ترجيح B بعد تأكيد شروط المرور والفتح.','القرار: B بشرط فحص الممر والباب.','Decision: prefer B subject to route and door verification.')),
[quiz('layout',q('إيه اللي يخلي مقارنة A وB عادلة؟','ما شرط المقارنة المنضبطة بين البديلين؟','وش يخلي المقارنة منضبطة؟','What makes the A/B comparison meaningful?'),q(['نفس الحدود والمستخدمين ومعايير القبول','تصغير أثاث البديل المفضل','الحكم بالتناظر فقط'],['ثبات الحدود والمستخدمين والمعايير','تغيير المقياس','التناظر وحده'],['نفس الحدود والمستخدمين والشروط','تغيير المقياس','التناظر فقط'],['Same boundaries, users and criteria','Shrink furniture in the favoured option','Judge symmetry alone']),q('الثوابت تمنع تحسين بديل شكليًا على حساب الوظيفة.','تتيح الثوابت تفسير الفرق الوظيفي الحقيقي.','الثوابت تظهر الفرق الوظيفي الحقيقي.','Fixed assumptions expose real functional differences.'))],
(q('ارسم بديلين لغرفة واحدة مع أنشطة وأسهم نظر ومسار حركة وشروط قبول، ثم برر اختيارك.','قدم بديلين بالمقياس نفسه مع الأنشطة والنظر والحركة وجدول قبول.','جهز بديلين لنفس الغرفة مع النشاط والنظر والمرور وسبب الاختيار.','Submit two same-scale layouts with activities, sightlines, circulation and acceptance criteria; justify the choice.'),q(['الأنشطة والمستخدمون','المخططان والحركة','جدول القبول والتنازل'],['البرنامج','مخططان','معايير وقرار'],['المستخدم والنشاط','المخططان','شروط وقرار'],['Users and activities','Two circulation plans','Criteria and trade-off']),q(['ثبات الافتراضات','قياس أضيق مرور','قرار مرتبط بالأولوية'],['افتراضات متطابقة','فحص الاستخدام','تعليل الاختيار'],['ثوابت واحدة','فحص الممر والفتح','اختيار مبرر'],['Consistent assumptions','Bottlenecks checked','Priority-based decision'])),
(q('التناظر معناه توزيع ناجح؟','هل يكفي التناظر للحكم على التوزيع؟','التناظر يكفي لنجاح الجلسة؟','Does symmetry prove a good layout?'),q('لا؛ لازم النشاط والنظر والمرور والفتح ينجحوا مع المستخدم الفعلي.','لا؛ تختبر الأنشطة والنظر والحركة والوصول.','لا، راجع النشاط والنظر والمرور والفتح مع المستخدم.','No. Test activities, sightlines, routes and openings for the actual users.'),'alternatives'))
lesson('M09-L02',q('مقاس الكنبة بره غير مقاس الجلسة اللي الجسم بيستخدمها. هنربط القعدة بالمستخدم والوضعية والوسادة، ونوثق تجربة قبل اعتماد المقاس.','تختلف الأبعاد الكلية عن أبعاد الجلوس الفعالة تحت الاستخدام. ستربط المستخدم والوضعية والدعم بمواصفة قابلة للتجربة والمراجعة.','مقاس الكنبة الخارجي مو نفسه مساحة الجلوس الفعلية. بنربط المستخدم ووضعية القعدة والدعم بتجربة ومواصفة واضحة.','Overall sofa dimensions differ from the effective seating dimensions experienced by a user. Link posture, support and cushion behaviour to a specification that can be tried and reviewed.'),[
sec('posture',q('ابدأ بالمستخدم ووضعية المهمة','تعريف المستخدم ووضعية الجلوس','ابدأ بالمستخدم وطريقة الجلوس','Start with the user and task posture'),q('اسأل المستخدم هيقعد يقرأ أو يتكلم أو يسترخي ولمدة قد إيه، وإزاي بيقعد ويقوم. راقب دعم القدمين والظهر والمسافة خلف الركبة أثناء تجربة نموذج. طول شخص لوحده مش كفاية لاختيار كرسي مناسب لكل الناس. اكتب ما يحتاج تجربة إضافية أو متطلب وصول خاص بدل تحويل ملاحظة فردية لمقاس مثالي عام.','حدد مهمة الجلوس ومدته وطريقة الدخول إلى المقعد والنهوض منه. راجع دعم القدمين والظهر والمنطقة خلف الركبة أثناء تجربة نموذج. لا يكفي طول المستخدم وحده لتحديد ملاءمة المقعد للجميع. وثق نتائج التجربة ومتطلبات الوصول أو التقييم الإضافي دون تعميم مقاس مثالي.','اسأل عن القراءة والكلام والاسترخاء ومدة الجلوس وطريقة القيام. جرّب دعم القدمين والظهر والحيز خلف الركبة على نموذج. طول الشخص لحاله ما يحدد مقعد مناسب للجميع. سجّل الملاحظات ومتطلبات الوصول أو التجربة الإضافية بدل تعميم مقاس واحد.','Define the task, sitting duration and how the user sits down and rises. In a mock-up, review foot and back support and the area behind the knee. Stature alone cannot establish a seat that suits everyone. Record observations and any access or further assessment needs rather than turning one user observation into a universal ideal dimension.'),q('المهمة وتجربة المستخدم تقود مواصفة الجلوس.','تراجع الوضعية في نموذج مع المستخدم المقصود.','المقاس المثالي العام مش بديل للتجربة.','Task-specific user trials inform the seating specification.')),
sec('effective',q('ميّز المقاس الكلي عن الفعّال','فصل الأبعاد الكلية والفعالة','ميّز الخارجي عن الجلسة الفعلية','Distinguish overall and effective dimensions'),q('العرض الكلي يشمل الذراعين، والعمق الكلي يشمل الظهر؛ ما ينفعش تعتبرهم مساحة جلوس صافية. ارسم قطاعًا يبين سطح الجلوس ودعم الظهر والوسادة وهي مستخدمة. في تمرين هندسي فقط: عرض كلي 1800 مم وذراعان 100 مم لكل واحد يعطي عرضًا صافيًا 1600 مم. الحساب لا يحدد عدد المستخدمين المريح ولا ارتفاع الجلسة تحت الحمل.','يشمل العرض الكلي الذراعين ويشمل العمق الكلي الظهر. يوضح القطاع أبعاد الاستخدام مع موضع دعم الظهر والوسادة تحت المستخدم. نفترض تدريبياً عرضاً كلياً 1800 مم وذراعين بعرض 100 مم لكل منهما؛ يصبح الصافي 1600 مم. لا يثبت الحساب سعة جلوس مريحة أو الارتفاع الفعال تحت الحمل.','العرض الخارجي فيه الذراعين والعمق الخارجي فيه الظهر. ارسم قطاع يوضح مساحة الاستخدام ودعم الظهر والوسادة أثناء الجلوس. بتمرين هندسي: عرض 1800 مم وذراع 100 مم بكل طرف يترك 1600 مم صافي. هذا ما يحدد عدد أشخاص مرتاحين ولا ارتفاع الجلسة تحت الاستخدام.','Overall width includes arms and overall depth includes the back. Draw a section showing the usable seat and back support with the cushion occupied. Geometry exercise only: an 1800 mm overall width with two 100 mm arms leaves 1600 mm clear. This arithmetic establishes neither comfortable occupancy nor effective loaded seat height.'),q('1800 − 100 − 100 = 1600 مم؛ فرض هندسي فقط.','الصافي منفصل عن الكلي وعن اعتماد الراحة.','الحساب يحدد الصافي مو راحة المستخدم.','Exercise: 1800 − 100 − 100 = 1600 mm clear.')),
sec('trial',q('وثّق تجربة واعتماد العينة','توثيق التجربة والعينة المرجعية','سجّل التجربة والعينة المعتمدة','Record the trial and reference sample'),q('جرّب عينة تمثل الهيكل والدعم والحشو المقترح، مش وسادة مختلفة فوق كرسي عشوائي. سجّل ارتفاع الجلسة وعمقها الفعّالين وحالة القياس وملاحظات الجلوس والقيام. تغيير الحشو أو ميل الظهر قد يغير الإحساس والأبعاد الفعالة؛ أعد التجربة بعد التغيير. اعتمد عينة مرجعية ومواصفة واضحة، وافصل قبول الراحة عن تحقق القوة والمتانة حسب متطلبات المنتج.','يجب أن تمثل العينة الهيكل والدعم والحشو المقترح. وثق الأبعاد الفعالة وحالة القياس وملاحظات الجلوس والنهوض. قد يغير الحشو أو ميل الظهر الإحساس والأبعاد، لذلك تعاد التجربة عند التعديل. اربط المواصفة بعينة مرجعية، وميّز قبول الراحة من تحقق القوة والمتانة وفق متطلبات المنتج.','جرّب عينة تمثل الهيكل والدعم والحشو الحقيقي المقترح. سجل الأبعاد الفعلية وحالة القياس وملاحظات القعدة والقيام. تغيير الحشو أو ميل الظهر ممكن يغير الراحة والمقاس الفعّال، فأعد التجربة. اربط المواصفة بعينة مرجعية، وخل تحقق القوة والمتانة منفصل عن قبول الراحة.','Use a sample representing the proposed frame, support and filling, not an unrelated cushion on a random chair. Record effective dimensions, measurement state and sitting/rising observations. Changes to filling or back angle may change feel and usable dimensions, so repeat the trial after changes. Tie the specification to a reference sample and distinguish comfort acceptance from required strength and durability verification.'),q('عينة ممثلة وملاحظات موثقة؛ التغيير يعيد المراجعة.','قبول الراحة لا يستبدل تحقق الأداء الإنشائي.','العينة تربط المواصفة بتجربة فعلية.','Comfort acceptance and structural performance are separate checks.'))],
(q('في تمرين 1800 مم مع ذراعين 100 مم، الصافي 1600 مم. اقترح المصمم توسيع كل ذراع إلى 150 مم مع ثبات الكلي؛ الصافي يصبح 1500 مم. قبل اعتماد المظهر الجديد نحدّث الرسم ونكرر تجربة الجلوس، لأن مساحة الاستخدام نقصت 100 مم حتى لو الطول الخارجي ثابت.','يبلغ الصافي 1600 مم في فرض العرض 1800 مم والذراعين 100 مم. عند زيادة كل ذراع إلى 150 مم مع ثبات الكلي يصبح الصافي 1500 مم. يوثق نقص الاستخدام 100 مم وتعاد تجربة الجلوس قبل اعتماد التعديل الشكلي.','الفرض 1800 مم وذراعين 100 مم يعطي صافي 1600 مم. إذا صار كل ذراع 150 مم وبقي الخارجي نفسه، الصافي 1500 مم. فقدنا 100 مم من الاستخدام؛ نحدث الرسم ونعيد التجربة قبل اعتماد الشكل.','The 1800 mm exercise with two 100 mm arms gives 1600 mm clear. Enlarging each arm to 150 mm while retaining overall width reduces clear space to 1500 mm. Update the drawing and repeat the user trial before approving the new appearance: usable width has decreased by 100 mm despite an unchanged outside length.'),q('القرار: الشكل الجديد يحتاج تحديث الصافي وتجربة مستخدم.','القرار: توثيق 1500 مم وإعادة تجربة الجلوس.','القرار: الصافي 1500 مم والتجربة تتعاد.','Decision: record 1500 mm clear and repeat the seating trial.')),
[quiz('clear-width',q('عرض 1800 مم وذراعان 150 مم؛ الصافي؟','ما الصافي لعرض 1800 مم وذراعين 150 مم؟','1800 مم و150 مم بكل ذراع؛ كم الصافي؟','1800 mm overall with two 150 mm arms: clear width?'),q(['1500 مم','1650 مم','1800 مم'],['1500 مم','1650 مم','1800 مم'],['1500 مم','1650 مم','1800 مم'],['1500 mm','1650 mm','1800 mm']),q('1800 − 150 − 150 = 1500 مم؛ لا يثبت الحساب الراحة.','يخصم الذراعان: الصافي 1500 مم.','نخصم الذراعين: 1500 مم حسب الفرض.','Subtract both arms: 1500 mm; this does not prove comfort.'))],
(q('اعمل بطاقة مستخدم وقطاع جلوس وحساب العرض، وسجل تجربة يميّز الراحة عن تحقق القوة.','قدم مواصفة جلوس مع المستخدم والقطاع والأبعاد وحالة التجربة ومتطلبات الأداء.','جهز بطاقة المستخدم وقطاع المقعد والحساب وسجل تجربة ومراجعة الأداء.','Submit a user brief, seat section, width calculation and trial record separating comfort from strength verification.'),q(['المستخدم والمهمة','الكلي والصافي وحالة القياس','العينة ونتيجة التجربة'],['المستخدم','القطاع والأبعاد','التجربة والأداء'],['المستخدم والمهمة','القطاع والمقاسات','العينة والتجربة'],['User and task','Overall/clear dimensions and measurement state','Sample and trial results']),q(['خصم الذراعين صحيح','قياس فعال موثق','عدم تعميم الراحة'],['صحة الحساب','وضوح حالة القياس','فصل الراحة والأداء'],['الحساب صحيح','حالة القياس واضحة','راحة بدون تعميم'],['Both arms deducted','Effective measurement state explicit','No universal comfort claim'])),
(q('نفس المقاس الخارجي يدي نفس الراحة؟','هل تضمن الأبعاد الكلية المتطابقة الراحة نفسها؟','نفس المقاس من بره يعني نفس الراحة؟','Do equal outside dimensions guarantee equal comfort?'),q('لا؛ الذراع والظهر والحشو والدعم يغيّروا الحيز الفعّال وتجربة المستخدم.','لا؛ تتأثر الراحة بالأبعاد الفعالة والدعم والحشو والوضعية.','لا، الذراع والظهر والحشو والدعم يغيرون الحيز والتجربة.','No. Arms, back, filling and support change effective space and user experience.'),'effective'))
lesson('M09-L03',q('التنجيد نظام طبقات، وكل طبقة ليها وظيفة. هنفصل الهيكل والدعم والحشو والكسوة، ونكتب مواصفة وفحص من غير اختزال الجودة في رقم كثافة.','يتكون التنجيد من هيكل ودعم وحشو وكسوة مترابطة. ستعد قطاع طبقات ومواصفة توريد وفحص تميز خصائص المواد من أداء التجميعة.','التنجيد طبقات لكل طبقة وظيفة. بنفصل الهيكل والدعم والحشو والكسوة ونكتب مواصفة وفحص بدل الحكم برقم كثافة واحد.','Upholstery is an assembly of frame, support, filling and cover. Produce a layer section and supply/inspection specification that separates material properties from assembly performance.'),[
sec('layers',q('ارسم الطبقات ومسار الحمل','تمثيل الطبقات ووظائفها','ارسم الطبقات ووظيفة كل وحدة','Draw layers and their functions'),q('من فوق لتحت في نموذج مقعد توضيحي: كسوة تغطي وتلامس المستخدم، حشو يشكل الإحساس، دعم مثل نظام أحزمة أو نوابض ينقل الحمل، وهيكل يحمل التجميعة. ممكن توجد طبقات فصل أو تغليف حسب النظام؛ الرسم مش وصفة ثابتة لكل كرسي. اربط كل طبقة بدورها وبطريقة تثبيتها أو استبدالها، ووضح مسار الحمل إلى الأرجل والأرض.','يظهر النموذج التوضيحي الكسوة والحشو ونظام الدعم والهيكل. قد تضاف طبقات فصل أو تغليف وفق التصميم، فلا يعمم ترتيب واحد على كل المقاعد. حدد وظيفة كل طبقة وارتباطها بالطبقات المجاورة وإمكان استبدالها، ثم تتبع انتقال الحمل إلى الأرجل والأرض.','بالنموذج التوضيحي: الكسوة تغطي وتلامس المستخدم، الحشو يشكل الإحساس، الدعم ينقل الحمل، والهيكل يحمل التجميعة. ممكن فيه طبقات فصل حسب النظام؛ مو وصفة ثابتة لكل كرسي. سجّل وظيفة الطبقة وتثبيتها واستبدالها ومسار الحمل للأرجل والأرض.','In an illustrative seat, the cover provides the contact surface, filling shapes the feel, a support system such as webbing or springs transfers load, and the frame carries the assembly. Separators or wraps may be added by the chosen system; this is not a universal recipe. Identify each layer’s role, attachment and replacement access, then trace load to legs and floor.'),q('كسوة وحشو ودعم وهيكل؛ أدوار مترابطة.','الرسم يوضح الوظائف ولا يفرض تجميعة موحدة.','كل طبقة لها دور ووصول محتمل للصيانة.','Cover, filling, support and frame form one assembly.')),
sec('specification',q('اكتب خواص مستقلة في المواصفة','فصل خصائص الحشو والكسوة','اكتب الخواص بدون خلط','Specify independent material properties'),q('كثافة الفوم هي كتلة لحجم، ومش هي نفسها الصلابة أو الإحساس بالجلوس. اطلب تعريف الخامة والكثافة وبيانات الصلابة أو الدعم وطريقة قياسها من المورد، واربطها بالعينة. للكسوة سجّل التركيب واللون واتجاه النسيج والتنظيف وبيانات الأداء المطلوبة للاستخدام. نتيجة اختبار تآكل وحدها ما تثبتش مقاومة بقع أو حريق؛ كل مطلب له دليل مناسب للتجميعة والسوق المستهدف.','تعبر كثافة الفوم عن الكتلة لكل حجم ولا تعادل الصلابة. توثق هوية الحشو والكثافة وخصائص الدعم وطريقة قياسها مع العينة المرجعية. تسجل للكسوة الخامة واللون واتجاه النسيج والتنظيف وأدلة الأداء المطلوبة. لا تستنتج مقاومة البقع أو الحريق من اختبار تآكل؛ يراجع كل مطلب بدليله المناسب للاستخدام والتجميعة.','كثافة الفوم كتلة بالنسبة للحجم، مو نفسها الصلابة أو إحساس القعدة. اطلب تعريف الخامة والكثافة وبيانات الدعم وطريقة قياسها واربطها بعينة. للكسوة سجل التركيب واللون واتجاه النسيج والتنظيف ودليل الأداء المطلوب. اختبار التآكل لحاله ما يثبت مقاومة البقع أو الحريق؛ كل مطلب يحتاج دليله المناسب.','Foam density is mass per volume, not the same property as firmness or sitting feel. Request material identity, density, firmness/support data and the measurement method, tied to a reference sample. For covers, record composition, colour, fabric direction, cleaning and required performance evidence. An abrasion result does not prove stain or fire performance; each requirement needs suitable evidence for the intended assembly and market.'),q('الكثافة ≠ الصلابة؛ كل مطلب له دليل مناسب.','لا تختزل أداء التجميعة في رقم مادة واحد.','المواصفة تفصل الهوية والخواص ودليل الأداء.','Density is not firmness; match evidence to each requirement.')),
sec('inspection',q('افحص العينة والتوريد والتجميع','تنظيم فحص التنجيد','افحص العينة والتوريد والمنتج','Inspect samples, deliveries and assembly'),q('احتفظ بعينة معتمدة ورقم تعريف الخامة. عند التوريد طابق النوع والدفعة واللون واتجاه النسيج قبل القص. أثناء التجميع راجع استواء الحشو وحماية الحواف واتجاه القطع وجودة الخياطة وإمكان فك الغطاء لو مطلوب. بعد التجميع راجع المظهر والراحة والصوت والحركة وفق خطة الفحص المعتمدة. لو اختلف المورد أو الحشو، سجّل تغييرًا وراجع أثره بدل قبول بديل بنفس اللون فقط.','تربط العينة المعتمدة برقم تعريف المادة. يفحص التوريد للنوع والدفعة واللون واتجاه النسيج قبل القص. يراجع التجميع لاستواء الحشو وحماية الحواف واتجاه القص والخياطة وإمكان نزع الغطاء إذا اشترط. يخضع المنتج للمظهر والراحة وبنود الأداء المعتمدة. أي استبدال للمورد أو المادة يوثق ويعاد تقييم أثره.','احفظ عينة معتمدة برقم الخامة. بالتوريد طابق النوع والدفعة واللون واتجاه النسيج قبل القص. بالتجميع راجع استواء الحشو والحواف واتجاه القص والخياطة وفك الغطاء إذا مطلوب. بعده افحص المظهر والراحة والبنود المعتمدة. تغيير المورد أو الحشو يتسجل ويتراجع؛ نفس اللون ما يكفي لقبول البديل.','Retain an approved sample and material identifier. Before cutting, check delivery identity, batch, colour and fabric direction. During assembly inspect filling consistency, edge protection, cutting direction, seams and removable-cover access if specified. Review appearance, comfort and approved performance checks after assembly. Record and assess supplier or filling substitutions rather than accepting an alternative merely because its colour matches.'),q('العينة مرجع، والتغيير له سجل ومراجعة.','الفحص يبدأ قبل القص ويستمر خلال التجميع.','نفس اللون ما يثبت تطابق الخامة.','Inspect before cutting and trace every substitution.'))],
(q('مورد قدم فومين بنفس الكثافة وقال إن الإحساس هيبقى واحد. نطلب تعريف كل خامة وبيانات الدعم وعينة تمثل نفس نظام المقعد. لو التجربة أظهرت اختلافًا، نسجل النتيجة ونختار حسب المواصفة المعتمدة. ما نرفعش كثافة الفوم تلقائيًا لعلاج أي مشكلة؛ سببها ممكن يبقى الدعم أو سمك الحشو أو هندسة المقعد.','يقدم المورد نوعين متساويي الكثافة مع ادعاء تماثل الإحساس. تطلب هوية النوع وبيانات الدعم وتجرب عينة في التجميعة نفسها. يسجل الاختلاف ويختار وفق المواصفة. لا تعالج كل ملاحظة بزيادة الكثافة؛ قد تنشأ من الدعم أو سماكة الحشو أو هندسة الجلوس.','المورد قدم نوعين بنفس الكثافة وقال نفس الإحساس. نطلب تعريف الخامة وبيانات الدعم ونجربهم في نفس تجميعة المقعد. نسجل الفرق ونختار حسب المواصفة. رفع الكثافة مو علاج تلقائي؛ المشكلة ممكن تكون بالدعم أو سماكة الحشو أو شكل الجلسة.','A supplier offers two foams with equal density and claims identical feel. Request each material identity and support data, then trial them in the same seating assembly. Record differences and select against the approved specification. Increasing density is not an automatic cure: the issue may arise from support, filling thickness or seat geometry.'),q('القرار: مقارنة خواص وعينة تجميعة، لا كثافة فقط.','القرار: تقييم المادة داخل التجميعة وفق المواصفة.','القرار: نراجع الخواص والعينة مع النظام.','Decision: assess properties and a representative assembly, not density alone.')),
[quiz('density',q('تساوي كثافة فومين يثبت إيه؟','ما الذي يثبته تساوي الكثافة فقط؟','نفس كثافة الفوم تعني وش؟','What does equal foam density alone establish?'),q(['تساوي خاصية الكتلة للحجم فقط','نفس الصلابة حتمًا','نفس أداء المقعد كله'],['تساوي الكتلة لكل حجم فقط','صلابة متطابقة','أداء كامل متطابق'],['تساوي الكتلة للحجم فقط','نفس الصلابة دائمًا','نفس أداء المقعد'],['Equal mass-per-volume property only','Necessarily identical firmness','Identical complete-seat performance']),q('الصلابة والدعم وأداء التجميعة خواص محتاجة بيانات وفحص منفصل.','تبقى الصلابة والدعم وأداء التجميعة بحاجة إلى أدلة مستقلة.','الصلابة والدعم وأداء المقعد تحتاج بيانات منفصلة.','Firmness, support and assembly performance require separate evidence.'))],
(q('ارسم طبقات مقعد وحدد وظيفة كل طبقة، واكتب مواصفة توريد وثلاث نقاط فحص قبل القص وبعد التجميع.','قدم قطاع طبقات ومواصفة مواد مرتبطة بعينة وخطة فحص وتوثيق استبدال.','جهز قطاع طبقات ومواصفة بعينة وخطة فحص للتوريد والتجميع والتغيير.','Submit a layer section, sample-linked material specification and inspection/substitution plan.'),q(['الطبقات ومسار الحمل','خواص المواد والعينة','فحص وتغيير'],['القطاع','المواصفة والعينة','الفحص والاستبدال'],['الطبقات','المواصفة والعينة','الفحص والتغيير'],['Layers and load path','Properties and reference sample','Inspection and substitution']),q(['تمييز الدعم والحشو','عدم مساواة الكثافة بالصلابة','تتبع الخامة قبل القص'],['وظائف صحيحة','خواص مستقلة','فحص قابل للتتبع'],['فصل الطبقات','الخواص بدون خلط','تتبع وفحص'],['Support/filling distinguished','Density not equated with firmness','Material traceability before cutting'])),
(q('اختبار تآكل القماش يثبت مقاومة الحريق؟','هل يثبت اختبار التآكل مقاومة الحريق؟','اختبار التآكل يكفي للحريق؟','Does an abrasion test prove fire performance?'),q('لا؛ دي مطالب مختلفة، وكل مطلب يحتاج دليل مناسب للخامة والتجميعة والاستخدام.','لا؛ لكل مطلب أداء دليل ملائم مستقل.','لا، كل مطلب له دليل مناسب للخامة والتجميعة والاستخدام.','No. These are different requirements and need appropriate material/assembly evidence.'),'specification'))
lesson('M09-L04',q('مش كل تغيير في شكل الكنبة تغيير بسيط. هنقارن بديلين لنفس الهيكل، وبعدين تغييرًا يمس مسار الحمل أو مساحة الجلوس ونحدد ملفه المطلوب.','تختلف التغييرات الشكلية عن التعديلات التي تمس الهيكل والدعم والأبعاد الفعالة. ستقارن بديلين لهيكل مشترك ثم بديلاً يحتاج مراجعة إنشائية.','مو كل تغيير بالشكل يكون بسيط. بنقارن بديلين على هيكل واحد ثم تغيير يمس الدعم أو الجلسة ونحدد وش يلزم مراجعته.','Appearance changes differ from changes affecting structure, support or usable seating. Compare two variants on one frame, then a third requiring construction review.'),[
sec('cosmetic',q('حدد الثوابت قبل بدائل الشكل','تعريف الثوابت في بدائل المظهر','حدد الثابت قبل تغيير الشكل','Lock the baseline before appearance variants'),q('ثبت رسم الهيكل والدعم وأبعاد الجلوس الفعالة، ثم اعمل A بكسوة ولون محددين وB بتوزيع لون أو تفصيل خياطة آخر. اكتب بالضبط ما اتغير وما ثبت. حتى تغيير الكسوة يحتاج مراجعة اتجاه النسيج والتنظيف والتمدد وطريقة الشد؛ كلمة شكلي مش إعفاء من مواصفة الخامة. المقارنة تبقى عادلة لما المنظور والمقياس وظروف عرض العينة ثابتة.','ثبت الهيكل والدعم والأبعاد الفعالة، ثم قارن كسوتين أو توزيعين للون والخياطة. سجل الثوابت والمتغيرات. يبقى تغيير الكسوة خاضعاً لمراجعة اتجاه النسيج والتنظيف والتمدد والشد؛ التصنيف الشكلي لا يلغي مواصفة المادة. استخدم مقياساً ومنظوراً وظروف عرض عينة متكافئة.','ثبت الهيكل والدعم وأبعاد الاستخدام ثم اعمل A وB بتوزيع لون أو خياطة مختلف. وضّح الثابت والمتغير. حتى الكسوة تحتاج فحص اتجاه النسيج والتنظيف والتمدد والشد؛ كلمة شكلي ما تلغي مواصفة الخامة. خلي المقياس والمنظور وعرض العينة ثابتين بالمقارنة.','Fix the frame, support and effective seating dimensions, then compare A/B cover, colour or seam layouts. Record what changes and what stays fixed. A cover change still needs review of fabric direction, cleaning, stretch and tensioning; “appearance” is not an exemption from material specification. Compare using equivalent scale, viewpoint and sample presentation conditions.'),q('A وB يشتركان في هيكل محدد وثوابت موثقة.','تصنيف التغيير لا يلغي فحص الخامة الجديدة.','ثبت الهيكل ووثّق تغيير الكسوة.','Shared frame, explicit variables and reviewed cover properties.')),
sec('structuralchange',q('اكتشف التغيير اللي يمس البناء','تمييز أثر التعديل على الهيكل','حدد التغيير اللي يمس الدعم','Identify changes that affect construction'),q('بديل C يشيل رجلًا وسطية عشان الشكل أخف. هنا مسار الحمل وبحر الجزء الحامل اتغيروا، حتى لو الكسوة نفسها. تعديل عرض الذراع أو ميل الظهر أو الوصلة ممكن يغيّر الجلسة أو القوى أو القص. علّم الأجزاء المتأثرة في الرسم، واطلب مراجعة تصميم وأداء للنظام المعدل قبل وصفه مكافئًا للأصل. ما تعوّضش الرجل المحذوفة بمسمار أكبر تخمينًا.','إزالة رجل وسطية لتخفيف المظهر تغير مسار القوى وبحر العنصر الحامل. وقد يغير عرض الذراع أو ميل الظهر أو الوصلة الأبعاد الفعالة والتصنيع. حدد الأجزاء المتأثرة واطلب مراجعة التصميم والأداء قبل اعتبار البديل مكافئاً. لا يستبدل التحقق بتكبير مسمار أو مقطع على أساس التخمين.','إذا C شال الرجل الوسطية لتخفيف الشكل، مسار الحمل وبحر العنصر الحامل تغيروا. عرض الذراع وميل الظهر والوصلات ممكن تغير الجلسة والتصنيع بعد. علّم الأجزاء المتأثرة وراجع التصميم والأداء قبل اعتبار البديل مكافئ. لا تعالج حذف الرجل بمسمار أكبر بالتخمين.','Variant C removes a centre leg for a lighter appearance. This changes load paths and the supported span even if upholstery remains identical. Arm width, back angle or joint changes can affect usable seating, forces and cutting patterns. Mark affected parts and require design/performance review before claiming equivalence. Do not compensate for a removed support by guessing a larger fastener.'),q('حذف دعم يغيّر مسار الحمل، مش المظهر بس.','يراجع التعديل وفق أثره لا حجمه المرئي.','التغيير الصغير بالشكل ممكن يغيّر البناء.','A visual change can alter the load path and supported span.')),
sec('decisionfile',q('اربط القرار بقائمة التغييرات','إعداد ملف مقارنة واعتماد التعديل','اربط الاختيار بسجل التغيير','Tie the decision to a change register'),q('جدول المقارنة يذكر لكل بديل: السبب، الأجزاء والخامات المتغيرة، أثره على القص والتنجيد والدعم، والعينة أو المراجعة المطلوبة. علّم الرسومات والجداول برقم مراجعة واحد حتى ما يتصنعش هيكل قديم مع كسوة جديدة غير مناسبة. الاختيار النهائي يوازن الوظيفة والمظهر وسهولة التصنيع والصيانة، مع إبقاء أي تحقق غير منتهٍ واضحًا بدل كلمة معتمد العامة.','تتضمن المقارنة سبب التغيير والأجزاء والمواد المتأثرة وأثرها على القص والتنجيد والدعم ومتطلبات العينة والمراجعة. اربط الرسومات والجداول برقم مراجعة متسق لمنع خلط إصدارات غير متوافقة. يوازن القرار الوظيفة والمظهر والتصنيع والصيانة، ويظهر ما بقي معلقاً للتحقق.','اكتب لكل بديل السبب والأجزاء والخامات المتغيرة وأثره على القص والتنجيد والدعم والعينة المطلوبة. خل الرسومات والجداول بنفس رقم المراجعة عشان ما ينخلط هيكل قديم بكسوة غير مناسبة. الاختيار يوازن الوظيفة والشكل والتصنيع والصيانة، ويبين التحقق اللي لسه ما اكتمل.','For each option record the reason, changed parts/materials, effects on cutting, upholstery and support, and required samples or reviews. Use consistent revision identifiers across drawings and schedules to prevent incompatible old/new parts being combined. Balance function, appearance, fabrication and serviceability, explicitly identifying outstanding checks rather than issuing an undifferentiated “approved” label.'),q('قرار واحد مرتبط برسوم ومواصفات بنفس المراجعة.','يظهر الجدول نطاق التغيير والتحقق المتبقي.','المراجعة تربط الشكل بملف التنفيذ.','A revision-controlled change register connects choice to fabrication.'))],
(q('A وB يشتركان في هيكل مع رجل وسطية، ويختلفان في توزيع اللون والخياطة. C يحذف الرجل. نراجع عينات كسوة A وB ونبقي الهيكل مرجعًا، لكن C يحتاج ملف تعديل للدعم ومراجعة أداء. اختيار لون B لا يعني اعتماد C؛ نسجل قرار اللون منفصلًا عن قرار البناء.','يشترك A وB في هيكل مدعوم وسطياً ويختلفان في اللون والخياطة. يحذف C الدعم الوسطي، فيحتاج ملف تعديل ومراجعة أداء. يمكن اختيار كسوة B بعد مراجعة العينة مع الإبقاء على الهيكل، دون أن ينتقل هذا القبول إلى C.','A وB نفس الهيكل مع رجل وسطية، والفرق لون وخياطة. C يحذف الرجل ويحتاج مراجعة بناء وأداء. ممكن نعتمد عينة كسوة B ونبقي الهيكل، لكن هذا ما يعتمد C؛ قرار اللون منفصل عن قرار الدعم.','A and B share a centre-supported frame and differ in colour/seam layout. C removes the centre support and requires a construction change file and performance review. Selecting B’s cover after sample review does not approve C’s structure. Record the appearance decision separately from the support decision.'),q('القرار: اختيار الكسوة لا يعتمد حذف الدعم.','القرار: فصل قبول المظهر عن اعتماد تعديل الهيكل.','القرار: الكسوة والدعم لهم قرارين موثقين.','Decision: cover selection does not approve support removal.')),
[quiz('change',q('أي تغيير يحتاج مراجعة لمسار الحمل؟','أي تعديل يغير مسار القوى مباشرة؟','وش التغيير اللي يراجع معه مسار الحمل؟','Which change directly calls for a load-path review?'),q(['حذف الرجل الوسطية','تغيير توزيع اللون فقط','تغيير خلفية صورة العرض'],['إزالة الدعم الوسطي','لون فقط','خلفية العرض'],['حذف الرجل الوسطية','توزيع اللون فقط','خلفية الصورة'],['Removing the centre leg','Colour layout only','Presentation background']),q('حذف الدعم يغيّر البحر ومسار الحمل حتى لو الشكل قريب.','يتغير البحر ومسار القوى عند حذف الدعم.','حذف الدعم يغير البحر ومسار الحمل.','Removing support changes the span and load path.'))],
(q('قدم A وB على هيكل واحد وC بتغيير دعم، مع رسومات وجدول أثر ورقم مراجعة وشروط قبول منفصلة.','أعد بديلين للمظهر وثالثاً لتعديل البناء مع سجل التغييرات والتحقق.','جهز بديلين بنفس الهيكل وثالث يغير الدعم مع سجل الأثر والتحقق.','Submit two same-frame appearance options and a support-changing third option, with an impact register and separate approval conditions.'),q(['ثوابت A وB','أثر C على الدعم','سجل المراجعات والقرار'],['البدائل والثوابت','الأثر الإنشائي','التغيير والتحقق'],['ثوابت البدائل','أثر الدعم','المراجعة والقرار'],['A/B baseline','C support impact','Revision and decision register']),q(['فصل الشكل والبناء','حصر الأجزاء المتأثرة','عدم اعتماد تحقق معلق'],['تصنيف صحيح','أثر موثق','حالة اعتماد واضحة'],['تمييز الشكل والدعم','أجزاء متأثرة واضحة','قرار بدون ادعاء'],['Appearance/construction separated','Affected parts listed','Outstanding checks remain explicit'])),
(q('تغيير لون القماش بسيط في كل الحالات؟','هل تغيير الكسوة قرار شكلي محض؟','تغيير الكسوة دايم بسيط؟','Is a cover change always purely cosmetic?'),q('مش بالضرورة؛ الخامة الجديدة قد تغير الشد والتنظيف والقص، فلازم مراجعة مواصفتها وعينتها.','ليس دائماً؛ تراجع خصائص المادة والشد والقص والتنظيف.','مو دائم، الخامة الجديدة ممكن تغير الشد والقص والتنظيف وتحتاج عينة ومواصفة.','Not always. Review the new material’s tensioning, cutting, cleaning and sample requirements.'),'cosmetic'))
