# Preserve readable LTR arithmetic in Arabic display strings without changing speech.
import re
for id in ['M08-L01','M08-L02','M08-L03','M09-L01','M09-L02','M09-L03','M09-L04']:
 for locale in LOCALES[:3]:
  f=ROOT/f'src/lib/technical-education/lessons/{id}__{locale}.json'
  def isolate(v):
   if isinstance(v,str):return re.sub(r'\d+(?:\s*[−×=+]\s*\d+)+',lambda m:'\u2066'+m.group()+'\u2069',v)
   if isinstance(v,list):return [isolate(x) for x in v]
   if isinstance(v,dict):return {k:isolate(x) for k,x in v.items()}
   return v
  f.write_text(json.dumps(isolate(json.loads(f.read_text())),ensure_ascii=False,indent=2)+'\n')
